@pytest.mark.asyncio
async def test_strategy_bfs_default_order() -> None:
    """BFS strategy visits pages in breadth-first order."""
    engine_config = CrawlConfig(crawl_strategy="bfs", max_concurrent=1, max_depth=2)
    engine = create_engine(engine_config)
    url = (
        os.environ.get("MOCK_SERVER_STRATEGY_BFS_DEFAULT_ORDER")
        or os.environ["MOCK_SERVER_URL"] + "/fixtures/strategy_bfs_default_order"
    )

    result = await crawl(engine, url)
    assert len(result.pages) == 5
    assert "alpha" in result.pages[1].url
    assert "beta" in result.pages[2].url
    assert "one" in result.pages[3].url
    assert "two" in result.pages[4].url


